// Real eBPF collector shim. Hides libbpf behind the tiny hh_bpf_* API.
//
// Requires the embedded ELF bytes generated by ./build.sh:
//   unsigned char hh_bpf_bpf_o[];
//   unsigned int  hh_bpf_bpf_o_len;
#include <errno.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <bpf/bpf.h>
#include <bpf/libbpf.h>

#include "hh_bpf.h"
#include "hh_bpf.bpf.o.inc"

static char g_last_error[256];

struct hh_bpf {
    struct bpf_object *obj;
    struct bpf_link *link;
    struct ring_buffer *rb;
    uint64_t count;
};

static void set_error(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(g_last_error, sizeof(g_last_error), fmt, ap);
    va_end(ap);
}

static int handle_event(void *ctx, void *data, size_t size)
{
    struct hh_bpf *h = ctx;
    (void)data;
    (void)size;
    h->count++;
    return 0;
}

int hh_bpf_open(struct hh_bpf **out)
{
    struct hh_bpf *h;
    struct bpf_program *prog;
    struct bpf_map *events_map;
    long lerr;
    int err;

    *out = NULL;
    g_last_error[0] = '\0';

    if (hh_bpf_bpf_o_len == 0) {
        set_error("eBPF object not embedded; run ./packets/build.sh");
        return -ENOENT;
    }

    h = calloc(1, sizeof(*h));
    if (!h) {
        set_error("out of memory");
        return -ENOMEM;
    }

    h->obj = bpf_object__open_mem(hh_bpf_bpf_o, hh_bpf_bpf_o_len, NULL);
    lerr = libbpf_get_error(h->obj);
    if (lerr) {
        set_error("bpf_object__open_mem: %s", strerror(-lerr));
        free(h);
        return (int)lerr;
    }

    err = bpf_object__load(h->obj);
    if (err) {
        set_error("bpf_object__load: %s", strerror(-err));
        bpf_object__close(h->obj);
        free(h);
        return err;
    }

    prog = bpf_object__find_program_by_name(h->obj, "on_retransmit");
    if (!prog) {
        set_error("program 'on_retransmit' not found");
        bpf_object__close(h->obj);
        free(h);
        return -ENOENT;
    }

    h->link = bpf_program__attach(prog);
    lerr = libbpf_get_error(h->link);
    if (lerr) {
        set_error("bpf_program__attach: %s", strerror(-lerr));
        bpf_object__close(h->obj);
        free(h);
        return (int)lerr;
    }

    events_map = bpf_object__find_map_by_name(h->obj, "events");
    if (!events_map) {
        set_error("map 'events' not found");
        bpf_link__destroy(h->link);
        bpf_object__close(h->obj);
        free(h);
        return -ENOENT;
    }

    h->rb = ring_buffer__new(bpf_map__fd(events_map), handle_event, h, NULL);
    if (!h->rb) {
        set_error("ring_buffer__new: %s", strerror(errno));
        bpf_link__destroy(h->link);
        bpf_object__close(h->obj);
        free(h);
        return -errno;
    }

    *out = h;
    return 0;
}

int hh_bpf_poll(struct hh_bpf *h, uint64_t *count, int timeout_ms)
{
    int err;

    if (!h || !h->rb)
        return -EINVAL;

    err = ring_buffer__poll(h->rb, timeout_ms);
    if (err < 0) {
        set_error("ring_buffer__poll: %s", strerror(-err));
        return err;
    }
    if (count)
        *count = h->count;
    return 0;
}

uint64_t hh_bpf_count(const struct hh_bpf *h)
{
    return h ? h->count : 0;
}

void hh_bpf_close(struct hh_bpf *h)
{
    if (!h)
        return;
    if (h->rb)
        ring_buffer__free(h->rb);
    if (h->link)
        bpf_link__destroy(h->link);
    if (h->obj)
        bpf_object__close(h->obj);
    free(h);
}

const char *hh_bpf_last_error(void)
{
    return g_last_error;
}
